import itertools, time
from scipy.optimize import least_squares
T0=time.time()
fT={'sin(w t)':lambda w: np.sin(w*t),'cos(w t)':lambda w: np.cos(w*t),'exp(-w t)':lambda w: np.exp(-w*t),'t^w':lambda w: t**w,'1/(1+w t)':lambda w: 1/(1+w*t),'t/(1+w t)':lambda w: t/(1+w*t)}
gX={'x':x,'v':v,'xv':x*v,'v2':v**2,'x2':x**2,'exp-x2':np.exp(-x**2),'1':np.ones_like(x),'v3':v**3,'xv2':x*v**2}
kX={'1':np.ones_like(x),'v':v,'x':x}
out=[]
for fn,fT_ in fT.items():
  for gn,g in gX.items():
    for kn,k in kX.items():
        def resid(p):
            a,b,c,d,e,w,h,q=p
            m=a*np.exp(-b*x**2)+c*(t**2/(1+d*t**2))*v**3+e*fT_(w)*g+h*k+q
            return m-dv_dt
        bestr=None
        for s in range(3):
            p0=np.random.RandomState(s+7).uniform(-1,2,8); p0[1]=0.4; p0[3]=0.4
            p0[5]=abs(p0[5])*0.5+0.1
            try:
                r=least_squares(resid,p0,max_nfev=300)
                if np.all(np.isfinite(r.fun)) and (bestr is None or r.cost<bestr.cost): bestr=r
            except Exception: pass
        if bestr is not None:
            out.append((np.mean(bestr.fun**2)/np.var(dv_dt),fn,gn,kn,bestr.x.round(3)))
